-- Q707: Derivatives and Hedging [easy/L2]
-- Issues: #1, #3
UPDATE questions SET
  choices = $EXPL$["Westbrook recognizes the $50,000 gain in earnings with an offsetting inventory adjustment; Crestone defers the $50,000 gain in OCI with no current earnings effect","Both companies recognize $50,000 in net income because ASC 815 treats all hedge types identically for income statement purposes","Westbrook defers the gain in OCI while Crestone recognizes it in earnings, because fair value hedges protect future transactions","Neither company recognizes any amount because perfectly effective hedges eliminate all gains and losses under ASC 815"]$EXPL$::jsonb,
