WHERE id = 707;

-- Q712: Derivatives and Hedging [hard/L1]
-- Issues: #1, #3
UPDATE questions SET
  choices = $EXPL$["The embedded derivative is clearly and closely related to the economic characteristics of the host contract","The host contract is already measured at fair value through earnings with changes recognized currently","The economic characteristics are not clearly and closely related to the host, and the hybrid instrument is not measured at FVTPL","The embedded derivative has a notional amount that exceeds a specified threshold set by the reporting entity"]$EXPL$::jsonb,
